const input = $input.first().json;

// Map content type to Canva template and dimensions
const templateMap = {
  'instagram_post': { template_id: '{{CANVA_TEMPLATE_IG_POST}}', design_type: 'InstagramPost', width: 1080, height: 1080 },
  'instagram_story': { template_id: '{{CANVA_TEMPLATE_IG_STORY}}', design_type: 'InstagramStory', width: 1080, height: 1920 },
  'instagram_reel': { template_id: '{{CANVA_TEMPLATE_IG_REEL}}', design_type: 'InstagramStory', width: 1080, height: 1920 },
  'facebook_post': { template_id: '{{CANVA_TEMPLATE_FB_POST}}', design_type: 'FacebookPost', width: 1200, height: 630 },
  'facebook_story': { template_id: '{{CANVA_TEMPLATE_FB_STORY}}', design_type: 'FacebookPost', width: 1080, height: 1920 },
  'tiktok_video': { template_id: '{{CANVA_TEMPLATE_TIKTOK}}', design_type: 'InstagramStory', width: 1080, height: 1920 },
  'linkedin_post': { template_id: '{{CANVA_TEMPLATE_LINKEDIN}}', design_type: 'LinkedInPost', width: 1200, height: 627 },
  'pinterest_pin': { template_id: '{{CANVA_TEMPLATE_PINTEREST}}', design_type: 'PinterestPin', width: 1000, height: 1500 },
  'email_banner': { template_id: '{{CANVA_TEMPLATE_EMAIL}}', design_type: 'EmailHeader', width: 600, height: 200 },
  'blog_header': { template_id: '{{CANVA_TEMPLATE_BLOG}}', design_type: 'BlogBanner', width: 1200, height: 628 }
};

const contentType = input.content_type || 'instagram_post';
const config = templateMap[contentType] || templateMap['instagram_post'];

// Build autofill data from AI-generated content
const autofillData = {};
if (input.headline) autofillData.headline = input.headline;
if (input.subheadline) autofillData.subheadline = input.subheadline;
if (input.body_text) autofillData.body = input.body_text;
if (input.cta_text) autofillData.cta = input.cta_text;
if (input.date_text) autofillData.date = input.date_text;
if (input.location_text) autofillData.location = input.location_text;

// Brand defaults
autofillData.brand_name = 'Mouvement Social Club';
autofillData.website = 'www.mouvementsocialclub.com';

return [{
  json: {
    design_title: input.design_title || `${contentType}_${new Date().toISOString().slice(0,10)}`,
    design_type: config.design_type,
    template_id: config.template_id,
    export_width: config.width,
    export_height: config.height,
    autofill_data: autofillData,
    content_type: contentType,
    original_post_id: input.post_id || null
  }
}];

